package com.cartoniq.stealthtext

import java.util.Locale

/** Order inside each row: English, Hindi, Urdu, Arabic, Bengali. Missing text falls back to English. */
object Lang {
    val codes = listOf("en", "hi", "ur", "ar", "bn", "es", "fr", "id", "tr", "pt", "ru", "fa", "ta", "te", "mr")
    val names = listOf("English", "हिन्दी", "اردو", "العربية", "বাংলা", "Español", "Français", "Bahasa Indonesia", "Türkçe", "Português", "Русский", "فارسی", "தமிழ்", "తెలుగు", "मराठी")

    fun isRtl(code: String): Boolean = code == "ur" || code == "ar" || code == "fa"

    fun initial(saved: String?): String {
        if (saved != null && saved in codes) return saved
        val dev = Locale.getDefault().language
        return if (dev in codes) dev else "en"
    }

    val map: Map<String, Map<String, String>> by lazy {
        val out = HashMap<String, HashMap<String, String>>()
        for (c in codes) out[c] = HashMap()
        for (row in rows) {
            for (i in 1 until minOf(5, codes.size)) {
                if (i < row.size && row[i].isNotEmpty()) out.getValue(codes[i])[row[0]] = row[i]
            }
        }
        for (row in extraRows) {
            for (j in 1 until row.size) {
                if (4 + j < codes.size && row[j].isNotEmpty()) out.getValue(codes[4 + j])[row[0]] = row[j]
            }
        }
        out
    }

